<?php declare(strict_types=1);
$page=max(1,(int)($_GET['page']??1));$q=trim((string)($_GET['q']??''));try{$suppliers=$application->soSuppliers()->paginate($q,$page,20);$total=$application->soSuppliers()->count($q);$soError=false;}catch(\Throwable){$suppliers=[];$total=0;$soError=true;}$adminContent=static function()use($suppliers,$total,$page,$q,$soError,$application):void{ ?><section class="admin-panel"><form class="admin-filters" method="get"><input name="q" value="<?=admin_h($q)?>" placeholder="Nome, CNPJ, contato ou telefone"><button class="btn btn-primary">Buscar</button></form><?php if($soError):admin_empty('SO indisponível','Não foi possível consultar as empresas do SO no momento.');elseif($suppliers===[]):admin_empty('Nenhum fornecedor encontrado','Não há fornecedores para os filtros informados.');else:?><div class="table-responsive"><table class="table os-table"><thead><tr><th>Nome</th><th>CNPJ</th><th>Contato</th><th>Telefone</th><th>Situação no Flux</th><th>Ações</th></tr></thead><tbody><?php foreach($suppliers as $supplier):$link=$application->adminCompanies()->integrationBySupplier($supplier->id);?><tr><td><?=admin_h($supplier->name)?></td><td><?=admin_h($supplier->document?:'Sem CNPJ')?></td><td><?=admin_h($supplier->contact)?></td><td><?=admin_h($supplier->phone)?></td><td><?=admin_h($link?'Vinculada a uma empresa':'Disponível para aprovação')?></td><td><?php if($link):?><a href="<?=admin_url('empresa.php?id='.(int)$link['empresa_id'])?>">Visualizar empresa</a><?php else:?><a class="btn btn-sm btn-primary" href="<?=admin_url('empresa.php?fornecedor_so='.$supplier->id)?>">Aprovar e cadastrar</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php admin_pagination($page,$total,20,'empresas-so.php',['q'=>$q]);endif;?></section><?php };
